xpath.script:
document.addEventListener('DOMContentLoaded', function () {

    /* 1️⃣ Change browser tab title safely */
    document.title = "Pending Quotations";

    /* 2️⃣ Change portal page heading safely */
    var titleEl =
        document.querySelector('.o_portal_searchbar h1') ||
        document.querySelector('.o_portal_searchbar_title') ||
        document.querySelector('h1');

    if (titleEl) {
        titleEl.textContent = "Pending Quotations";
    }

    /* 3️⃣ Change breadcrumb text safely */
    var breadcrumb = document.getElementById('portal_breadcrumbs_sale');
    if (breadcrumb) {
        breadcrumb.textContent = "Pending Quotations";
    }
});
